/**
 * @file main.c
 * @brief lvgl_sim 入口：参数解析 → LVGL 初始化 → 场景 → 主循环。
 *
 *   ./lvgl_sim                       # 默认 demo 场景，240x320 @2x 窗口
 *   ./lvgl_sim --scene vmap          # vmap 底图 mock
 *   ./lvgl_sim --scale 3             # 放大到 3 倍
 *   ./lvgl_sim --headless --frames 40 --shot out.png
 */

#include <getopt.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include "sim.h"

uint32_t sim_tick_ms(void);

static uint32_t s_vtick;

static uint32_t vtick_get(void)
{
    return s_vtick;
}

static const char *const kUsageLines[] = {
    "用法: lvgl_sim [选项]",
    "  -s, --scene NAME    场景（demo | vmap | ui），默认 demo",
    "  -S, --size WxH      设备分辨率，默认 240x320（设备原生竖屏）",
    "  -k, --scale N       窗口放大倍数，默认 2",
    "  -H, --headless      不建窗口，跑固定帧数",
    "  -f, --frames N      headless 帧数，默认 30",
    "  -o, --shot PATH     headless 截图输出 PNG",
    "  -t, --title TEXT    窗口标题",
    "      --ui-tour DIR   巡页模式（仅 --scene ui）：逐页/逐主题截图到 DIR",
    "      --tour-frames N 巡页每页等待帧数，默认 90",
    "  -l, --list          列出所有场景",
    "  -h, --help          本帮助",
    NULL,
};

static void usage(void)
{
    for (int i = 0; kUsageLines[i]; i++) {
        puts(kUsageLines[i]);
    }
}

int main(int argc, char **argv)
{
    sim_cfg_t cfg;
    memset(&cfg, 0, sizeof(cfg));
    cfg.width = 240;
    cfg.height = 320;   /* 设备原生竖屏：状态栏 24 + 页面 296 */
    cfg.scale = 2;
    cfg.frames = 30;
    cfg.tour_frames = 90;
    cfg.title = "lvgl_sim";

    const char *scene_name = "demo";
    bool list_only = false;

    enum {
        OPT_UI_TOUR = 256,
        OPT_TOUR_FRAMES,
    };

    static const struct option long_opts[] = {
        { "scene",    required_argument, 0, 's' },
        { "size",     required_argument, 0, 'S' },
        { "scale",    required_argument, 0, 'k' },
        { "headless", no_argument,       0, 'H' },
        { "frames",   required_argument, 0, 'f' },
        { "shot",     required_argument, 0, 'o' },
        { "title",    required_argument, 0, 't' },
        { "ui-tour",  required_argument, 0, OPT_UI_TOUR },
        { "tour-frames", required_argument, 0, OPT_TOUR_FRAMES },
        { "list",     no_argument,       0, 'l' },
        { "help",     no_argument,       0, 'h' },
        { NULL, 0, NULL, 0 },
    };

    int c;
    while ((c = getopt_long(argc, argv, "s:S:k:Hf:o:t:lh", long_opts, NULL)) != -1) {
        switch (c) {
            case 's': scene_name = optarg; break;
            case 'S':
                if (sscanf(optarg, "%dx%d", &cfg.width, &cfg.height) != 2) {
                    fprintf(stderr, "bad --size\n");
                    return 2;
                }
                break;
            case 'k': cfg.scale = atoi(optarg); break;
            case 'H': cfg.headless = true; break;
            case 'f': cfg.frames = atoi(optarg); break;
            case 'o': cfg.shot = optarg; break;
            case 't': cfg.title = optarg; break;
            case OPT_UI_TOUR: cfg.ui_tour = optarg; break;
            case OPT_TOUR_FRAMES: cfg.tour_frames = atoi(optarg); break;
            case 'l': list_only = true; break;
            case 'h': usage(); return 0;
            default: usage(); return 2;
        }
    }

    if (list_only) {
        sim_scene_list();
        return 0;
    }

    const sim_scene_t *scene = sim_scene_find(scene_name);
    if (!scene) {
        fprintf(stderr, "unknown scene\n");
        sim_scene_list();
        return 2;
    }

    lv_init();
    lv_tick_set_cb(cfg.headless ? vtick_get : sim_tick_ms);

    if (!sim_display_init(&cfg)) {
        return 1;
    }
    sim_lvgl_bind();

    scene->create(lv_screen_active(), &cfg);
    printf("lvgl_sim: scene=%s %dx%d scale=%d %s\n", scene->name, cfg.width,
           cfg.height, cfg.scale, cfg.headless ? "headless" : "window");

    if (cfg.ui_tour != NULL && cfg.tour_frames <= 0) {
        cfg.tour_frames = 90;
    }

    if (cfg.headless) {
        /* 巡页模式下帧数由巡页状态机自己决定，这里只给一个死循环保护。
         * 只有 `ui` 场景会真正启用巡页（见 scenes.c）；其它场景带 --ui-tour
         * 也完全按原来的 --frames 跑。 */
        int frames = cfg.frames;

#ifdef SIM_WITH_UI
        const bool tour = sim_ui_tour_enabled();

        if (tour) {
            frames = 6000;
        }
#endif
        for (int i = 0; i < frames; i++) {
            s_vtick += 16;
            lv_timer_handler();
#ifdef SIM_WITH_UI
            if (tour && sim_ui_tour_done()) {
                break;
            }
#endif
        }
        if (cfg.shot) {
            int w = 0;
            int h = 0;
            const uint16_t *fb = sim_display_shadow(&w, &h);

            if (!sim_png_write(cfg.shot, fb, w, h)) {
                fprintf(stderr, "failed to write png\n");
                sim_display_shutdown();
                return 1;
            }
            printf("shot -> %s (%dx%d)\n", cfg.shot, w, h);
        }
    } else {
        while (sim_display_pump()) {
            uint32_t idle = lv_timer_handler();

#ifdef SIM_WITH_UI
            if (sim_ui_tour_enabled() && sim_ui_tour_done()) {
                break;
            }
#endif
            if (idle < 1) {
                idle = 1;
            }
            if (idle > 16) {
                idle = 16;
            }
            usleep(idle * 1000);
        }
    }

    sim_display_shutdown();
    return 0;
}

/**
 * @file ui_boot.c
 * @brief `ui` 场景：把 vendor/my_vendor 的真实 UI 启动起来。
 *
 * 这个函数**照抄** `ui/bicycle/src/bicycle_c_main.c` 的 `main()`，只做两处替换：
 *   1. 板级 LCD / `lv_nuttx_init()` 那几步去掉 —— display 已经由模拟器的
 *      `sim_lvgl_bind()` 建好（X11 窗口或 headless 影子缓冲），这里用
 *      `lv_display_get_default()` 拿同一个句柄；
 *   2. `lv_init()` 不调（`src/main.c` 已经调过）。
 *
 * 剩下的顺序与板端一致：黑屏/停刷新 → 注册 flush done 回调（板级，略）→
 * `lvgl_page_init()` → `open_boot_sequence()` → `sync_boot()` → 开刷新 →
 * `bicycle_mtp_ui_init()` → `lvgl_page_set_app_started(true)` → `ui_ctl_ready()`。
 *
 * 板端 `while (1)` 里的每拍工作（ctl 队列、传感器同步、演示模式、主题换装）
 * 由 `ui_tick_cb` 这个 10 ms 的 LVGL 定时器承担 —— 它就在 `lv_timer_handler()`
 * 里跑，等价于板端"循环顶 + 帧后"两段逻辑的合并版。
 */

#include <stdio.h>
#include <sys/stat.h>
#include <unistd.h>

#include "sim.h"
#include "sim_config.h"

#include "lvgl_page.h"
#include "bicycle_demo.h"
#include "bicycle_mtp_ui.h"
#include "bicycle_runtime.h"
#include "bicycle_ui_ctl.h"
#include "helm_palette.h"
#include "live_map/map_page.h"
#include "lv_pm_theme.h"
#include "myvendor_identity.h"
#include "startup/startup_page.h"
#include "Vendor/Board/lv_port/lv_port_buttons.h"

/** 板端 `BICYCLE_LOOP_SLEEP_MS`：主循环 10 ms 一拍。 */
#define SIM_UI_TICK_MS 10u

static bool s_started;
static bicycle_mtp_ui_t s_mtp_ui;

/**
 * @brief 板端 while(1) 的主体（去掉 usleep 与 watchdog/性能探针）。
 *
 * 顺序照抄 `bicycle_c_main.c`：ctl 队列 → 传感器 → 演示 →（帧后）主题重活。
 */
static void sim_ui_loop_body(void)
{
    map_page_t *page = lvgl_page_map();

    bicycle_mtp_ui_run(&s_mtp_ui);
    bicycle_ui_ctl_poll(page);
    bicycle_runtime_sync_companion_sensors();
    bicycle_demo_poll();

    /* 这两步在板端放在 lv_timer_handler() 之后（帧后做换主题的重活），
     * 在定时器回调里已经是"帧内"，顺序等价。 */
    helm_theme_poll_apply();
    lv_pm_theme_poll_styles();

    if (page && !lvgl_page_is_usb_transfer()) {
        map_page_debug_snap(page);
    }
}

static void ui_tick_cb(lv_timer_t *tmr)
{
    (void)tmr;
    sim_ui_loop_body();
}

/* 板端 `vmap_map_catalog.c` 把地图目录存进 **64 字节** 的 `char map_dir[64]`，
 * PC 上那条 mkfs 绝对路径（90+ 字符）会被截断 ⇒ 找不到瓦片、地图空白。
 * 所以给一个短路径，指向设备真正烧的那份网格包。 */
static void ensure_short_map_path(void)
{
    const char *short_path = "/tmp/vmap";
    struct stat st;

    if (lstat(short_path, &st) == 0) {
        return;
    }
    if (symlink(SIM_VMAP_REAL_DIR, short_path) != 0) {
        fprintf(stderr, "sim_ui: 建不了 %s -> %s（地图会空白）\n",
                short_path, SIM_VMAP_REAL_DIR);
    }
}

void sim_ui_start(void)
{
    lv_display_t *disp;
    lv_obj_t *scr;
    lv_timer_t *refr;
    map_page_t *page;
    int rc;

    if (s_started) {
        return;
    }
    s_started = true;

    ensure_short_map_path();

    disp = lv_display_get_default();
    if (disp == NULL) {
        fprintf(stderr, "sim_ui: no display (sim_lvgl_bind 没跑？)\n");
        return;
    }

    printf("sim_ui: boot start %dx%d\n", (int)lv_display_get_horizontal_resolution(disp),
           (int)lv_display_get_vertical_resolution(disp));

    /* ── 与 bicycle_c_main.c 完全一致的前奏 ────────────────────────────── */
    scr = lv_display_get_screen_active(disp);
    lv_obj_set_style_bg_color(scr, lv_color_black(), 0);
    lv_obj_set_style_bg_opa(scr, LV_OPA_COVER, 0);
    /* 开机时先不让 LVGL 刷：板端是为了把 2SFBL 的像素留在屏上。 */
    lv_display_enable_invalidation(disp, false);
    refr = lv_display_get_refr_timer(disp);
    if (refr) {
        lv_timer_pause(refr);
    }

    lv_display_set_antialiasing(disp, true);

    /* CONFIG_MYVENDOR_LCD_DISP 的 flush done 回调是板级 /dev/lcd0 的东西，模拟器
     * 的 flush_cb 自己调 lv_display_flush_ready()，不需要也不该再注册。 */

    /* 按键：PC 上 lv_port_buttons.c 整份被 `#if defined(__NuttX__)` 关掉，
     * 这里调用的是它自己的空实现，与板端保持同一调用点。 */
    lv_port_buttons_init();

    lvgl_page_init();

    rc = lvgl_page_open_boot_sequence();
    if (rc != 0) {
        fprintf(stderr, "sim_ui: lvgl_page_open_boot_sequence failed (%d)\n", rc);
        return;
    }

    if (!myvendor_is_factory()) {
        startup_page_sync_boot();
    }

    printf("sim_ui: pages registered, splash open\n");

    /* splash / 工厂页用编译进去的 helm 点阵字体，先画一帧再谈 TTF / MTP / vmap */
    lv_display_enable_invalidation(disp, true);
    refr = lv_display_get_refr_timer(disp);
    if (refr) {
        lv_timer_resume(refr);
    }
    scr = lv_display_get_screen_active(disp);
    lv_obj_invalidate(scr);
    lv_obj_update_layout(scr);
    lv_refr_now(disp);

    page = lvgl_page_map();
    if (!page) {
        printf("sim_ui: splash active, LiveMap loads under Startup\n");
    }

    /* MTP：模拟器没有 USB 端点，不启 worker（myvendor_mtp_init 是板级线程），
