      slot = &s_probe.fl[s_probe.fl_n++];
      slot->x1 = area->x1;
      slot->y1 = area->y1;
      slot->x2 = area->x2;
      slot->y2 = area->y2;
      slot->n = 0;
    } else {
      slot = &s_probe.fl[0];
