static void wp_dump_window(uint32_t win)
{
  uint32_t i;
  char b[64];
  size_t off = 0;

  if (s_probe.obj_n == 0 && s_probe.flush_n == 0 && s_probe.darea_n == 0) {
    return;
  }

  b[0] = '\0';
  for (i = 0; i < 9; i++) {
    off += (size_t)snprintf(b + off, sizeof(b) - off, "%s%u", i ? "," : "",
                            (unsigned)s_probe.bucket[i]);
  }

  syslog(LOG_WARNING,
         "[inval] S win=%u obj=%u objpx=%u darea=%u dareapx=%u refr_req=%u "
         "refr=%u flush=%u flushpx=%u b=%s z=%u",
         (unsigned)win, (unsigned)s_probe.obj_n, (unsigned)s_probe.obj_px,
         (unsigned)s_probe.darea_n, (unsigned)s_probe.darea_px,
         (unsigned)s_probe.refr_req, (unsigned)s_probe.refr_start,
         (unsigned)s_probe.flush_n, (unsigned)s_probe.flush_px, b,
         (unsigned)s_probe.zero_n);

  for (i = 0; i < s_probe.top_n; i++) {
    wp_top_t *t = &s_probe.top[i];

    syslog(LOG_WARNING,
           "[inval] T i=%u n=%u px=%u area=%dx%d@%d,%d kind=%s txt=\"%s\" "
           "obj=%p ra=0x%lx",
           (unsigned)i, (unsigned)t->n, (unsigned)t->px, (int)t->w, (int)t->h,
           (int)t->x, (int)t->y, t->kind, t->txt, (void *)t->obj,
           (unsigned long)t->ra);
  }

  for (i = 0; i < s_probe.fl_n; i++) {
    wp_flush_t *f = &s_probe.fl[i];

    syslog(LOG_WARNING, "[inval] F n=%u area=(%d,%d)-(%d,%d) %dx%d px=%u",
           (unsigned)f->n, (int)f->x1, (int)f->y1, (int)f->x2, (int)f->y2,
           (int)(f->x2 - f->x1 + 1), (int)(f->y2 - f->y1 + 1),
           (unsigned)((f->x2 - f->x1 + 1) * (f->y2 - f->y1 + 1)));
  }
}

static void wp_reset_window(void)
{
  memset(&s_probe, 0, sizeof(s_probe));
  s_probe.win_start = lv_tick_get();
  s_probe.win_started = true;
}

static void wp_tick_cb(lv_timer_t *tmr)
{
  uint32_t now = lv_tick_get();
  uint32_t win;

  LV_UNUSED(tmr);

  if (!s_probe.win_started) {
    s_probe.win_start = now;
    s_probe.win_started = true;
    return;
  }

  win = lv_tick_elaps(s_probe.win_start);
  if (win < WP_WIN_MS) {
    return;
  }

  wp_dump_window(win);
  wp_reset_window();
}

static void bicycle_inval_disp_event(lv_event_t *e)
{
  lv_event_code_t code = lv_event_get_code(e);

  switch (code) {
    case LV_EVENT_INVALIDATE_AREA: {
      lv_area_t *area = lv_event_get_invalidated_area(e);

      s_probe.darea_n++;
      if (area != NULL) {
        int32_t w = lv_area_get_width(area);
        int32_t h = lv_area_get_height(area);

        if (w > 0 && h > 0) {
          s_probe.darea_px += (uint32_t)w * (uint32_t)h;
        }
      }
      break;
    }
    case LV_EVENT_REFR_REQUEST:
      s_probe.refr_req++;
      break;
    case LV_EVENT_REFR_START:
      s_probe.refr_start++;
      break;
    case LV_EVENT_FLUSH_START: {
      lv_area_t *area = lv_event_get_param(e);

      if (area != NULL) {
        int32_t w = lv_area_get_width(area);
        int32_t h = lv_area_get_height(area);

        s_probe.flush_n++;
        if (w > 0 && h > 0) {
          s_probe.flush_px += (uint32_t)w * (uint32_t)h;
        }
        wp_flush_add(area);
      }
      break;
    }
    default:
      break;
  }
}

/**
 * @brief 自行车 inval probe init。
 * @return 0 成功，负 errno 失败。
 */
void bicycle_inval_probe_init(lv_display_t *disp)
{
  lv_display_add_event_cb(disp, bicycle_inval_disp_event,
                          LV_EVENT_INVALIDATE_AREA, NULL);
  lv_display_add_event_cb(disp, bicycle_inval_disp_event, LV_EVENT_REFR_REQUEST,
                          NULL);
  lv_display_add_event_cb(disp, bicycle_inval_disp_event, LV_EVENT_REFR_START,
                          NULL);
  lv_display_add_event_cb(disp, bicycle_inval_disp_event, LV_EVENT_FLUSH_START,
                          NULL);
  s_probe.win_start = lv_tick_get();
  s_probe.win_started = true;
  lv_timer_create(wp_tick_cb, WP_TICK_MS, NULL);
  syslog(LOG_NOTICE, "[inval] probe on (WP-UIFIX/R1 object-hook build)");
}
